@@ -1,3 +1,16 @@
-export function sgdStep(w: number[], g: number[], lr = 0.05): void {
-  for (let i = 0; i < w.length; i++) w[i] -= lr * g[i];
-}
+export class Adam {
+  private m: number[] = []; private v: number[] = []; private t = 0;
+  constructor(private lr = 0.01, private b1 = 0.9, private b2 = 0.999, private eps = 1e-8) {}
+  step(w: number[], g: number[]): void {
+    if (this.m.length === 0) { this.m = g.map(() => 0); this.v = g.map(() => 0); }
+    this.t++;
+    for (let i = 0; i < w.length; i++) {
+      this.m[i] = this.b1 * this.m[i]! + (1 - this.b1) * g[i]!;
+      this.v[i] = this.b2 * this.v[i]! + (1 - this.b2) * g[i]! * g[i]!;
+      const mh = this.m[i]! / (1 - this.b1 ** this.t), vh = this.v[i]! / (1 - this.b2 ** this.t);
+      w[i] -= this.lr * mh / (Math.sqrt(vh) + this.eps);
+    }
+  }
+}

