-export const prep = (x: number[][]) => x;
+export function standardise(train: number[][], test: number[][]): [number[][], number[][]] {
+  const d = train[0]!.length, n = train.length;
+  const mean = Array.from({ length: d }, (_, j) => train.reduce((s, r) => s + r[j]!, 0) / n);
+  const sd = Array.from({ length: d }, (_, j) => Math.sqrt(train.reduce((s, r) => s + (r[j]! - mean[j]!) ** 2, 0) / n) || 1);
+  const f = (x: number[][]) => x.map((r) => r.map((v, j) => (v - mean[j]!) / sd[j]!));
+  return [f(train), f(test)];
+}

